var convertLengthTool = {
  name: "convert_length",
  description: "\u7C73\u4E0E\u5398\u7C73\u6362\u7B97",
  parameters: {
    type: "object",
    additionalProperties: false,
    required: ["value", "from", "to"],
    properties: {
      value: { type: "number", description: "\u5F85\u6362\u7B97\u6570\u503C\uFF0C\u5FC5\u987B\u4E3A\u975E\u8D1F\u6570" },
      from: { type: "string", enum: ["m", "cm"], description: "\u6765\u6E90\u5355\u4F4D\uFF1Am \u6216 cm" },
      to: { type: "string", enum: ["m", "cm"], description: "\u76EE\u6807\u5355\u4F4D\uFF1Am \u6216 cm" }
    }
  },
  output: {
    schema: {
      type: "object",
      additionalProperties: false,
      required: ["value", "unit"],
      properties: {
        value: { type: "number", description: "\u6362\u7B97\u7ED3\u679C\u6570\u503C" },
        unit: { type: "string", enum: ["m", "cm"], description: "\u7ED3\u679C\u5355\u4F4D" }
      }
    },
    render: (_args, value) => {
      return [{ type: "text", text: JSON.stringify(value) }];
    }
  },
  execute: async (args, _exec) => {
    const { value, from, to } = args ?? {};
    if (typeof value !== "number" || !Number.isFinite(value)) {
      throw new Error("convert_length \u53C2\u6570\u9519\u8BEF\uFF1Avalue \u5FC5\u987B\u662F\u6570\u503C");
    }
    if (value < 0) {
      throw new Error("convert_length \u53C2\u6570\u9519\u8BEF\uFF1Avalue \u5FC5\u987B\u4E3A\u975E\u8D1F\u6570\u503C");
    }
    if (from !== "m" && from !== "cm") {
      throw new Error("convert_length \u53C2\u6570\u9519\u8BEF\uFF1Afrom \u4EC5\u652F\u6301 m \u6216 cm");
    }
    if (to !== "m" && to !== "cm") {
      throw new Error("convert_length \u53C2\u6570\u9519\u8BEF\uFF1Ato \u4EC5\u652F\u6301 m \u6216 cm");
    }
    if (from === to) {
      return { value, unit: to };
    }
    return { value: from === "m" ? value * 100 : value / 100, unit: to };
  }
};
var name = "convert-length-tool";
var inject = ["tools"];
function apply(ctx) {
  ctx.tools.register(convertLengthTool);
}
export {
  apply,
  inject,
  name
};

/**
 * convert_length —— 米/厘米换算原生工具（LangChain 迁移）
 * 来源：source-4d12592a-9148-4ad0-b554-3d450a3b4ed1 / agent.ts 的 convert 工具（langchain tool + zod schema）。
 * 契约：DSH 原生工具 ToolDefinition —— name/description/parameters + output.schema/render + async execute
 * （已对照官方 @deepseek-ai/dsh-tools lib/types 的 ToolDefinition/defineTool 合同，687f282e 与运行时 source.lock 一致）。
 * 语义保留：value 非负（错误语义保留）、from/to 仅 m|cm 枚举、同单位原样返回、m→cm ×100、cm→m ÷100、结构化成功输出 {value, unit}。
 * 本模块是受控插件入口（导出 name/inject/apply），经 assets/build 编译为同名 convert-length.mjs，
 * 由 Preset agent.cordis.yml 以 /opt/dsh-managed/convert-length.mjs 挂载；不包装 LangChain 运行时，无需来源框架。
 */

/** 单位枚举，与来源 z.enum(['m', 'cm']) 对应。 */
type LengthUnit = 'm' | 'cm'

interface ConvertLengthArgs {
  value: number
  from: LengthUnit
  to: LengthUnit
}

interface ConvertLengthResult {
  value: number
  unit: LengthUnit
}

/** 本地结构化契约（与官方 ToolDefinition 对应，避免任何外部运行时依赖）。 */
interface TextBlock {
  type: 'text'
  text: string
}

interface ConvertLengthToolDefinition {
  name: string
  description: string
  parameters: Record<string, unknown>
  output: {
    schema: Record<string, unknown>
    render: (args: ConvertLengthArgs, value: ConvertLengthResult) => TextBlock[]
  }
  execute: (args: ConvertLengthArgs, exec: unknown) => Promise<ConvertLengthResult>
}

const convertLengthTool: ConvertLengthToolDefinition = {
  name: 'convert_length',
  description: '米与厘米换算',
  parameters: {
    type: 'object',
    additionalProperties: false,
    required: ['value', 'from', 'to'],
    properties: {
      value: { type: 'number', description: '待换算数值，必须为非负数' },
      from: { type: 'string', enum: ['m', 'cm'], description: '来源单位：m 或 cm' },
      to: { type: 'string', enum: ['m', 'cm'], description: '目标单位：m 或 cm' },
    },
  },
  output: {
    schema: {
      type: 'object',
      additionalProperties: false,
      required: ['value', 'unit'],
      properties: {
        value: { type: 'number', description: '换算结果数值' },
        unit: { type: 'string', enum: ['m', 'cm'], description: '结果单位' },
      },
    },
    render: (_args: ConvertLengthArgs, value: ConvertLengthResult): TextBlock[] => {
      return [{ type: 'text', text: JSON.stringify(value) }]
    },
  },
  execute: async (args: ConvertLengthArgs, _exec: unknown): Promise<ConvertLengthResult> => {
    const { value, from, to } = (args ?? {}) as ConvertLengthArgs
    // 来源 z.number().nonnegative() 的错误语义：受强制 JSON Schema 子集无 minimum 关键字限制，在此保留拒绝语义。
    if (typeof value !== 'number' || !Number.isFinite(value)) {
      throw new Error('convert_length 参数错误：value 必须是数值')
    }
    if (value < 0) {
      throw new Error('convert_length 参数错误：value 必须为非负数值')
    }
    if (from !== 'm' && from !== 'cm') {
      throw new Error('convert_length 参数错误：from 仅支持 m 或 cm')
    }
    if (to !== 'm' && to !== 'cm') {
      throw new Error('convert_length 参数错误：to 仅支持 m 或 cm')
    }
    // 同单位原样返回（来源语义保留）
    if (from === to) {
      return { value, unit: to }
    }
    return { value: from === 'm' ? value * 100 : value / 100, unit: to }
  },
}

/** Cordis 插件名。 */
const name = 'convert-length-tool'
/** 该工具使用的服务。 */
const inject = ['tools']

/** 注册 convert_length 原生工具（ctx.tools.register → ToolDefinition）。 */
function apply(ctx: { tools: { register: (definition: ConvertLengthToolDefinition) => unknown } }): void {
  ctx.tools.register(convertLengthTool)
}

export { apply, inject, name }
